Value.Code:
// lote ficou na linha e sobrou so a loco: devolve direto, sem ir ao ponto nem a saida
Log.info("GesDVs", "devolveu_loco", texto_trem((Trem) agent) + " | na linha " + linha_destino);
// linha_destino nao e zerada aqui: o lote pode sair do deixar_lote depois da loco e o colocar_lote usa ela
log_terminou_manobra((Trem) agent);
trem_em_manobra = null;
formando        = false;
// se o lote já foi colocado, a próxima manobra pode começar; senão o lote_estacionado libera
if (get_lote(linha_destino) != null) liberar_proxima_manobra();

colocar_lote(linha_destino, (Trem) agent);
// caso da loco sozinha que saiu antes do lote: a manobra já terminou, libera a próxima
if (trem_em_manobra == null) liberar_proxima_manobra();

// saída das DVs: val_via2 + isn_linha02_e (travessão do ISN); o cruzamento veio antes, no pegar_cruzamento_saida.
// o trem que segue direto sai pela track199 -> val_via2 -> AMV da porteira
// o liberar_faixas_circulacao (depois do trainExit) solta junto com as outras faixas do trem
main().gestorDeCirculacao.faixa_val_via2.ocupar((Trem) agent);
main().gestorDeISN.faixa_isn_linha02_e.ocupar((Trem) agent);
Log.info("GesDVs", "ocupar_val_via2_saida", String.format("trem=%d pegou", agent.getId()));
main().gestorDeCirculacao.log_pegou_licenca((Trem) agent, "ocupar_val_via2_saida");

// entrada nas linhas das DVs passa pelo cruzamento da porteira (AMV railwaySwitch27)
// o liberar_faixas_ponto solta quando a cauda sai do cruzamento
Log.info("GesDVs", "seize_cruzamento_entrada", String.format("trem=%d pegou", agent.getId()));
main().gestorDeCirculacao.log_pegou_licenca((Trem) agent, "seize_cruzamento_entrada");

// saída das DVs: primeiro o cruzamento da porteira (senha da área), sozinho; depois val_via2 + isn_linha02_e
Log.info("GesDVs", "pegar_cruzamento_saida", String.format("trem=%d pegou", agent.getId()));
main().gestorDeCirculacao.log_pegou_licenca((Trem) agent, "pegar_cruzamento_saida");
